DECLARE @open TIME(3) = '08:30:00.000';
DECLARE @close TIME(3) = '17:15:30.500';

SELECT
    @open    AS opens_at,
    @close   AS closes_at,
    DATEDIFF(MINUTE,
        CAST('08:30' AS DATETIME2),
        CAST('17:15' AS DATETIME2))          AS minutes_open,   -- 525
    CAST(SYSDATETIME() AS TIME(0))           AS current_time_of_day;
